import type { ComponentPropsWithoutRef } from "react";
import { cn } from "../../lib/cn";
import "../../styles/label.css";

export interface LabelProps extends ComponentPropsWithoutRef<"label"> {
  /** Shows a required marker. Pair it with `required` on the control. */
  required?: boolean;
}

/** Standalone label for controls that are not inside a <Field>. Use Field when you can. */
export function Label({ required, className, children, ...props }: LabelProps) {
  return (
    <label className={cn("eui-label", className)} {...props}>
      {children}
      {required ? (
        <span className="eui-label__required" aria-hidden="true">
          *
        </span>
      ) : null}
    </label>
  );
}

/**
 * Joins class names, skipping falsy values.
 * Kept tiny on purpose: components own their class lists, so no merge step is needed.
 */
export function cn(...inputs: Array<string | false | null | undefined>): string {
  return inputs.filter(Boolean).join(" ");
}

/* Label. Standalone form label, matching the Field label. */

.eui-label {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  font-size: 14px;
  font-weight: 500;
  color: var(--eui-color-fg);
}

.eui-label__required {
  color: var(--eui-color-danger);
}
